// 解析RSS Feed并提取最新文章
const xml2js = require('xml2js');
const he = require('he'); // HTML实体解码

// 解析XML数据
const parser = new xml2js.Parser();
let rssData;

try {
  rssData = await new Promise((resolve, reject) => {
    parser.parseString($input.first().json.data, (err, result) => {
      if (err) reject(err);
      else resolve(result);
    });
  });
} catch (error) {
  throw new Error('RSS解析失败: ' + error.message);
}

const items = rssData.rss?.channel?.[0]?.item || [];
let latestArticle = null;
let latestPubDate = 0;

// 根据发布日期找到最新文章
for (const item of items) {
  const pubDate = new Date(item.pubDate[0]).getTime();
  if (pubDate > latestPubDate) {
    latestPubDate = pubDate;
    latestArticle = item;
  }
}

if (latestArticle) {
  const link = latestArticle.link[0];
  const title = latestArticle.title[0];

  // 从链接中提取slug
  // 例如: https://neican.huangzuomin.com/newspaper/2025-06-23-06-23-ai-/ -> 2025-06-23-06-23-ai-
  const parts = link.split('/').filter(p => p);
  const slug = parts[parts.length - 1];

  // 构建GitHub raw URL
  const githubRawUrl = `https://raw.githubusercontent.com/huangzuomin/AInews/main/content/newspaper/${slug}.md`;

  return [{
    json: {
      rss_title: he.decode(title),
      rss_link: link,
      rss_pubDate: latestPubDate,
      rss_slug: slug,
      github_raw_url: githubRawUrl
    }
  }];
} else {
  return []; // 没有找到文章
}

// 解析Markdown文件并准备Steemit发布数据
const yaml = require('js-yaml');

const markdownContent = $input.first().json.data;
const frontMatterRegex = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/;
const match = markdownContent.match(frontMatterRegex);

let frontMatter = {};
let body = markdownContent;

if (match) {
  try {
    frontMatter = yaml.load(match[1]);
    body = match[2];
  } catch (e) {
    console.error('YAML Front Matter解析错误:', e);
    // 回退：当作没有front matter或格式错误
  }
}

// Steemit需要parent_permlink用于顶级帖子，通常是根标签如'test'或'cn'
// 对于此工作流，我们使用文章的第一个标签作为parent_permlink
// 如果没有标签或第一个标签无效，使用默认值如'hive'或'cn'
let parentPermlink = 'cn'; // 没有有效标签时的默认值

// 处理标签
let tags = [];
if (frontMatter.tags) {
  if (Array.isArray(frontMatter.tags)) {
    tags = frontMatter.tags.map(tag => String(tag).toLowerCase().replace(/[^a-z0-9-]/g, '')).filter(tag => tag);
  } else if (typeof frontMatter.tags === 'string') {
    tags = frontMatter.tags.split(/[,\s]+/).map(tag => String(tag).toLowerCase().replace(/[^a-z0-9-]/g, '')).filter(tag => tag);
  }
  if (tags.length > 5) {
    tags = tags.slice(0, 5); // Steemit最多5个标签
  }
  if (tags.length > 0) {
    parentPermlink = tags[0]; // 使用第一个标签作为parent_permlink
  }
}

// 生成Steemit Permlink
let steemitPermlink = frontMatter.slug || frontMatter.permlink; // 优先级：使用现有的slug/permlink
if (!steemitPermlink) {
  // 回退：从标题生成
  steemitPermlink = frontMatter.title
    ? frontMatter.title.toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '') // 移除非字母数字字符，除了空格和连字符
        .replace(/\s+/g, '-')       // 将空格替换为连字符
        .replace(/^-+|-+$/g, '')    // 去除开头和结尾的连字符
    : `post-${Date.now()}`; // 最后的回退方案
}

// 确保permlink安全且足够唯一
// 对于生产环境，考虑检查与Steemit的唯一性或在不够唯一时添加时间戳
// 对于此工作流，我们依赖slug/生成的标题结合发布频率足够唯一

return [{
  json: {
    title: frontMatter.title,
    body: body.trim(), // 去除正文的前后空白
    tags: tags,
    permlink: steemitPermlink,
    parent_permlink: parentPermlink,
    // 传递原始RSS slug用于更新最后发布记录
    rss_slug: $input.first().json.rss_slug
  }
}];

// RSS Feed错误处理
console.error('RSS Feed获取失败:', $input.first().error.message);
return [{
  json: {
    error: 'RSS Feed获取失败',
    message: $input.first().error.message,
    timestamp: new Date().toISOString()
  }
}];

// Markdown内容获取错误处理
console.error('Markdown内容获取失败:', $input.first().error.message);
return [{
  json: {
    error: 'Markdown内容获取失败',
    message: $input.first().error.message,
    timestamp: new Date().toISOString()
  }
}];

// Steemit发布错误处理
console.error('Steemit发布失败:', $input.first().error.message);
return [{
  json: {
    error: 'Steemit发布失败',
    message: $input.first().error.message,
    timestamp: new Date().toISOString()
  }
}];
